const $ = s=>document.querySelector(s);
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={image:'M3 4h20v18H3zM3 17l6-6 5 5 3-3 6 6M18 7h.01',file:'M5 2h10l6 6v16H5zM15 2v7h6M9 14h8M9 18h8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',library:'M4 4h5v16H4zM11 4h4v16h-4zM17 5l4-1 3 15-4 1z',pen:'m15 5 4 4M4 20l4-1L21 6a2.8 2.8 0 0 0-4-4L4 15z',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 11h16M8 15h2M14 15h2',box:'m3 7 9-4 9 4v11l-9 4-9-4zM3 7l9 5 9-5M12 12v10',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 4v16M4 12h16',arrow:'M4 12h16M14 6l6 6-6 6',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',check:'m5 12 4 4L20 5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2'};
const icon=(name)=>`<svg viewBox="0 0 26 26" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const btn=(label,action,kind='',data='')=>`<button class="btn ${kind}" data-action="${action}" ${data}>${label}</button>`;
const labels={overview:'运营总览',library:'灵感收藏',images:'图片',studio:'创作工作台',calendar:'发布排期',accounts:'账号管理',product:'产品资料',settings:'设置与接入'};
const statusNames={draft:'草稿',scheduled:'已排期',blocked:'待接通 / 待处理',uncertain:'待核对',publishing:'发布中',published:'已核对发布',cancelled:'已取消',failed:'失败',needs_source:'待补截图',ready:'待分析',analyzed:'已分析',saved:'已收藏'};
const badge=(status)=>`<span class="badge ${['blocked','uncertain','needs_source'].includes(status)?'warn':['draft','saved','ready','cancelled'].includes(status)?'neutral':''}">${esc(statusNames[status]||status)}</span>`;
const date=(d)=>new Date(d).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
let S, page=location.hash.slice(1)||'overview', selected=null, edit=null, dirty=false, slide=0, filter='all', query='', busy=false, toastTimer, accountFilter='all', accountView='active', productTab='facts', assetFilter='all', imageToolTab='adjust', imageSourceId=null, imageOutputName='', imagePrompt='', imageAIMode='generate', imageSize='1024x1536', imageReferenceIds=[], cropSettings={ratio:'3:4',fit:'contain',zoom:1,x:0,y:0}, cropRevision=0, cropReady=false, generationAssetIds=[], authUser=null, authRedirecting=false;
const imageAssetCache=new Map();
function authRequired(){imageAssetCache.clear();imagePrompt='';imageReferenceIds=[];imageSourceId=null;cropReady=false;dirty=false;S=null;edit=null;authUser=null;const app=$('#app');if(app){app.hidden=true;app.innerHTML='';}const dialog=$('#modal');if(dialog?.open)dialog.close();const content=$('#modal-content');if(content)content.innerHTML='';if(!authRedirecting){authRedirecting=true;location.replace('/login');}const error=new Error('请先登录');error.code='AUTH_REQUIRED';return error;}
async function validateSession({restoring=false}={}){if(authRedirecting)return false;try{const response=await fetch('/api/auth/session',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(15000)});if(response.status===401)throw authRequired();if(!response.ok)throw new Error();const session=await response.json();if(typeof session.authenticated!=='boolean')throw new Error();if(!session.authenticated)throw authRequired();authUser=session.user||authUser;return true;}catch(error){if(error.code!=='AUTH_REQUIRED'&&restoring)authRequired();return false;}}
async function restoreSession(event){if(!event.persisted)return;const app=$('#app'),dialog=$('#modal'),dialogWasHidden=dialog?.hidden;if(app)app.hidden=true;if(dialog)dialog.hidden=true;if(authRedirecting){location.replace('/login');return;}if(await validateSession({restoring:true})&&!authRedirecting){if(app)app.hidden=false;if(dialog)dialog.hidden=dialogWasHidden;}}
async function api(url,body,method='POST'){const r=await fetch('/api/'+url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},...(body!==undefined?{body:JSON.stringify(body)}:{})});if(r.status===401)throw authRequired();let value;try{value=await r.json();}catch{throw Error('服务暂时不可用，请检查本地服务');}if(!r.ok)throw Error(value.error||'操作失败');return value;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
async function refresh(renderPage=true){S=await api('state',undefined,'GET');if(accountFilter!=='all'&&!allAccounts().some(a=>a.id===accountFilter))accountFilter='all';if(renderPage)render();}
function allAccounts(){return S.accounts||[];}
function activeAccounts(){return allAccounts().filter(a=>!a.archived);}
function accountById(id){return allAccounts().find(a=>a.id===id);}
function accountName(id){return accountById(id)?.name||'未分配账号';}
function chosenAccount(){return accountById(accountFilter)||accountById(S.defaultAccountId)||activeAccounts()[0];}
function accountReady(id){return Boolean(S.capabilities.accounts?.[id]?.publisher);}
function scoped(items){return accountFilter==='all'?items:items.filter(x=>x.accountId===accountFilter);}
function accountOptions(value,{all=false,archived=false}={}){return `${all?'<option value="all">全部账号</option>':''}${allAccounts().filter(a=>archived||!a.archived||a.id===value).map(a=>`<option value="${esc(a.id)}"${a.id===value?' selected':''}>${esc(a.name)}${a.archived?' · 已归档':!a.enabled?' · 已停用':''}${a.id===S.defaultAccountId?' · 默认':''}</option>`).join('')}`;}
function accountSelect(name,value,label='所属账号'){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="accountId">${accountOptions(value)}</select></div>`;}
function accountTag(id,snapshot=''){return `<span class="account-tag">${esc(accountById(id)?.name||snapshot||'未分配账号')}</span>`;}
function contentMode(d){return d?.contentMode==='text'?'text':'image';}
function contentBadge(value){return `<span class="badge neutral">${(typeof value==='string'?value:contentMode(value))==='text'?'文字':'图文'}</span>`;}
function jobContentMode(job){return job.contentMode||contentMode(S.drafts.find(d=>d.id===job.draftId));}
function nativeTextHint(){return S?.capabilities?.textPublisher?'使用小红书默认配图，样式在发布端选择。':'原生配图待发布端接通';}
function modeSelect(scope,value='image'){return `<div class="field"><label for="${scope}-content-mode">发稿方式</label><select id="${scope}-content-mode" name="contentMode"><option value="image"${value==='image'?' selected':''}>图文稿</option><option value="text"${value==='text'?' selected':''}>文字稿</option></select></div>`;}
function imageShareValue(settings){return Number.isInteger(settings?.imageShare)?Math.min(100,Math.max(0,settings.imageShare)):70;}
function draftCurrent(){const items=scoped(S.drafts);return items.find(d=>d.id===selected)||items[0];}
function nav(to){if(dirty&&!confirm('草稿有未保存的修改，确定离开吗？'))return;dirty=false;edit=null;slide=0;page=labels[to]?to:'overview';location.hash=page;render();window.scrollTo(0,0);}
function field(label,name,value,type='text',hint=''){return `<div class="field"><label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" rows="5">${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}">`}${hint?`<small>${hint}</small>`:''}</div>`;}
function topHead(title,action=''){return `<header class="page-head"><h1>${title}</h1><div class="actions">${['overview','studio','calendar'].includes(page)?`<select id="account-filter" class="account-filter" aria-label="筛选账号">${accountOptions(accountFilter,{all:true,archived:true})}</select>`:''}${action}</div></header>`;}
function connectors(){const account=chosenAccount(),ready=account&&accountReady(account.id);return `<div class="connect-row"><div><div class="connect-title">${icon('spark')}AI 创作模型</div><p>${S.capabilities.ai?esc(S.capabilities.model):'未配置'}</p></div><span class="badge ${S.capabilities.ai?'':'neutral'}">${S.capabilities.ai?'已配置':'待配置'}</span></div><div class="connect-row"><div><div class="connect-title">${icon('link')}小红书发布器</div><p>${account?esc(account.name)+' · '+(ready?'目标已配置，待实际核对':'未配置发布目标'):'请先添加账号'}</p></div><span class="badge ${ready?'':'neutral'}">${ready?'已配置':'未接通'}</span></div><div class="connect-row"><div><div class="connect-title">${icon('box')}飞书产品资料</div><p>手动资料</p></div><span class="badge neutral">未同步</span></div>`;}

function overview(){const drafts=scoped(S.drafts),jobs=scoped(S.jobs),account=chosenAccount(),dailySettings=account?.settings||S.settings;const pending=drafts.filter(d=>d.status==='draft').length;const scheduled=jobs.filter(j=>j.status==='scheduled').length;const published=jobs.filter(j=>j.status==='published').length;
return topHead('运营总览',`<div class="actions">${btn(icon('plus')+' 收藏灵感','upload','light')}${btn('新建草稿','generate')}</div>`)+`<section class="stats">${[['灵感收藏',S.inspirations.length,'份','把喜欢的内容留在这里'],['待打磨草稿',pending,'篇','有想法，也有产品依据'],['等待发布',scheduled,'篇',S.settings.enabled?'每日任务已开启':'每日任务尚未开启'],['实际已发布',published,'篇',published?'已取得核对后的笔记链接':'还没有真实发布记录']].map(([l,n,u,f],i)=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-value">${n}<span>${u}</span></div></div>`).join('')}</section><div class="dashboard-columns"><section><div class="section-head"><h2>最近草稿</h2>${btn('全部草稿','nav','ghost','data-page="studio"')}</div><div class="draft-list">${drafts.slice(0,3).map(d=>`<article class="draft-row">${draftThumbnail(d)}<div class="draft-row-info"><h3>${esc(d.title)}</h3><div class="draft-meta">${badge(d.status)}${contentBadge(d)}${accountTag(d.accountId)}<span>${esc(d.series)}${contentMode(d)==='image'?' · '+draftPhotos(d).length+' 张':''}</span></div></div>${btn('编辑','edit','light',`data-id="${d.id}"`)}</article>`).join('')||`<div class="empty">暂无草稿${btn('新建草稿','generate')}</div>`}</div><div class="section-head"><h2>最近收藏</h2>${btn('全部收藏','nav','ghost','data-page="library"')}</div>${S.inspirations.slice(0,2).map(r=>`<div class="draft-row"><div class="avatar">↗</div><div class="draft-row-info"><h3>${esc(r.title)}</h3><div class="draft-meta">${esc(r.tags.slice(0,3).join(' / '))}</div></div>${btn('查看','reference','ghost',`data-id="${r.id}"`)}</div>`).join('')}</section><aside><div class="section-head"><h2>接入状态</h2></div><div class="panel">${connectors()}<div class="note-box">现在可以收藏、编辑、导出与排期。实际分析和发布需接通对应服务。</div>${btn('管理接入 →','nav','ghost','data-page="settings"')}</div><div class="section-head"><h2>每日任务</h2></div><div class="panel"><h3>${account?esc(account.name):'暂无账号'}</h3><p class="preview-caption">${dailySettings?.enabled?'已启用':'未启用'} · ${esc(dailySettings?.time||'10:00')}<br>${esc(dailySettings?.timezone||'Asia/Shanghai')} · ${dailySettings?.mode==='review'?'审核后发布':'自动生成并发布'}<br>图文 ${imageShareValue(dailySettings)}% · 文字 ${100-imageShareValue(dailySettings)}%</p>${account&&!account.archived?btn('设置','daily','ghost',`data-id="${account.id}"`):''}</div></aside></div>`;}
function library(){let items=S.inspirations.filter(r=>(filter==='all'||(filter==='pool'?r.pool:r.status===filter))&&[r.title,...r.tags,r.note].join(' ').toLowerCase().includes(query.toLowerCase()));
return topHead('灵感收藏',btn(icon('plus')+' 收藏灵感','upload'))+`<div class="filters">${[['all','全部收藏'],['analyzed','已分析'],['ready','待分析'],['pool','每日选题池']].map(([key,label])=>`<button class="filter ${filter===key?'active':''}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}<label class="search"><input id="library-search" type="search" aria-label="搜索收藏" placeholder="搜索标题、标签、备注…" value="${esc(query)}"></label></div><div class="library-grid">${items.map((r,i)=>`<article class="ref-card"><button class="ref-cover" data-action="reference" data-id="${r.id}" aria-label="查看 ${esc(r.title)}">${r.assets[0]?`<img src="${esc(r.assets[0])}" alt="收藏的参考截图"><span class="cover-shade"></span><span class="cover-label">REFERENCE / ${String(i+1).padStart(2,'0')}</span>`:`<div class="text-cover"><div class="mono">SAVED REFERENCE / ${String(i+1).padStart(2,'0')}</div><h3>${esc(r.title)}</h3><div class="big-arrow">↗</div></div>`}</button><div class="ref-info"><h3>${esc(r.title)}</h3><div class="tags">${r.tags.slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')||'<span class="tag">未分类</span>'}</div><div class="ref-footer">${badge(r.status)}${btn('参考创作','generate','ghost',`data-id="${r.id}"`)}</div></div></article>`).join('')}<button class="upload-card" data-action="upload"><span class="plus">+</span><strong>添加收藏</strong><p>上传一组截图，或保存一个链接<br>相同笔记与截图会自动合并</p></button></div>${!items.length&&S.inspirations.length?'<p class="preview-caption">没有匹配的收藏，试试其他关键词。</p>':''}`;}
function studio(){const d=draftCurrent();if(!d)return topHead('创作工作台',btn('新建草稿','generate'))+`<div class="empty">暂无草稿</div>`;
  if(!edit||edit.id!==d.id){edit=structuredClone(d);edit.contentMode=contentMode(d);edit.productAssetIds||=[];edit.slides||=[];selected=d.id;slide=0;}
  const issues=S.draftChecks[d.id]||[],imageMode=contentMode(edit)==='image';
  return topHead('创作工作台',btn(icon('plus')+' 新建草稿','generate'))+`<div class="actions draft-toolbar"><select id="draft-select" class="draft-select" aria-label="选择草稿">${scoped(S.drafts).map(x=>`<option value="${x.id}"${x.id===d.id?' selected':''}>${esc(x.title)} · ${contentMode(x)==='text'?'文字':'图文'} · ${esc(accountName(x.accountId))}</option>`).join('')}</select><span class="badge neutral">${d.method==='ai'?'AI 生成':d.method==='template'?'本地事实模板':'编辑样例'}</span><span class="grow"></span>${btn('复制为新稿','duplicate','ghost',`data-id="${d.id}"`)}${btn('历史版本','history','ghost',`data-id="${d.id}"`)}</div><div class="studio-grid"><section class="editor"><form id="draft-form"><div class="form-grid">${accountSelect('draft-account',edit.accountId)}${modeSelect('draft',contentMode(edit))}</div>${imageMode?assetPicker(edit.productAssetIds,'draft'):`<p class="mode-note">${nativeTextHint()}</p>`}${field('笔记标题','title',edit.title)}<div class="field-footer"><span></span><span id="title-count">${[...edit.title].length} / 20</span></div><div class="spacer"></div>${field('正文','body',edit.body,'textarea')}<div class="field-footer"><span></span><span id="body-count">${[...edit.body].length} / 1000</span></div><div class="spacer"></div><div class="form-grid">${field('话题标签 · 用逗号分隔','tags',edit.tags.join('，'))}<div class="field"><label for="series">内容栏目</label><select id="series" name="series">${['通信小麻烦','接通实验','一起打磨'].map(x=>`<option${edit.series===x?' selected':''}>${x}</option>`).join('')}</select></div></div>${imageMode?`<details class="slide-fields"><summary>辅助分镜 · ${edit.slides.length} 页</summary><p class="mode-note">仅用于内容策划，不作为发布图片。</p>${edit.slides.map((p,i)=>`<div class="slide-field"><label for="slide-title-${i}">分镜 ${i+1}</label><input id="slide-title-${i}" data-slide="${i}" data-key="headline" aria-label="第${i+1}页标题" value="${esc(p.headline)}"><textarea data-slide="${i}" data-key="body" aria-label="第${i+1}页正文" rows="3">${esc(p.body)}</textarea><button type="button" class="btn ghost" data-action="remove-slide" data-index="${i}">移除此页</button></div>`).join('')}${btn('＋ 加一页','add-slide','light')}</details>`:''}<div class="spacer"></div>${field('待补事实或素材 · 每行一项','gaps',edit.gaps.join('\n'),'textarea')}<div class="review-box ${issues.length?'issues':''}"><strong>${issues.length?'待处理':'基础检查通过'}</strong>${issues.length?`<ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="muted">${d.approved?'已标记审核通过':'尚未审核'} · 修改保存后需重新审核</p></div><div class="actions"><button class="btn" type="submit">保存草稿</button>${btn('核对通过','approve','light',`data-id="${d.id}"`)}${btn(icon('calendar')+' 安排发布','schedule','light',`data-id="${d.id}"`)}<span id="save-state" class="muted save-state">已保存 · v${d.revision}</span></div></form></section><aside class="preview-panel"><div class="preview-top"><span>${imageMode?'发布图片':'文字预览'}</span><span id="page-indicator"></span></div><div id="draft-preview"></div><div class="preview-pagination"></div><p id="preview-source" class="preview-source"></p><div class="actions">${btn(icon('download')+(imageMode?' 导出图文包':' 导出文案'),'export','light')}${imageMode?btn('下载当前图片','download-slide','ghost'):''}</div><p class="preview-caption">${imageMode?'使用所选产品原图，不叠加标题。':nativeTextHint()}</p><details class="preview-reference"><summary>参考说明</summary><p class="preview-caption">${esc(d.adaptation||'根据产品资料组织内容。')}</p>${d.referenceIds.map(rid=>{const r=S.inspirations.find(x=>x.id===rid);return r?btn(esc(r.title),'reference','ghost',`data-id="${rid}"`):'<small class="muted">原参考已删除</small>';}).join('')}</details></aside></div>`;}

function calendar(){const dailyAccounts=(accountFilter==='all'?activeAccounts():allAccounts().filter(a=>a.id===accountFilter));return topHead('发布排期',btn('每日任务设置','daily','light'))+`<div class="calendar-layout"><section><div class="daily-account-list">${dailyAccounts.map(a=>`<div class="panel daily-account-row"><div><strong>${esc(a.name)}</strong><span class="badge ${a.enabled&&!a.archived?'':'neutral'}">${a.archived?'已归档':a.enabled?'启用':'停用'}</span><p>${a.settings.enabled?'每日任务已开启':'每日任务未开启'} · ${esc(a.settings.time)} · ${esc(a.settings.timezone)} · ${a.settings.mode==='automatic'?'自动发布':'审核后发布'} · 图文 ${imageShareValue(a.settings)}%</p></div>${!a.archived?btn('设置','daily','light',`data-id="${a.id}"`):''}</div>`).join('')||'<div class="empty">暂无账号</div>'}</div><div class="section-head"><h2>发布队列</h2><span class="muted" style="font-size:11px">按浏览器时区显示</span></div><div class="jobs">${scoped(S.jobs).slice().sort((a,b)=>b.scheduledAt.localeCompare(a.scheduledAt)).map(j=>{const dt=new Date(j.scheduledAt);return `<article class="job"><div class="job-date"><span>${dt.getMonth()+1} 月</span><b>${dt.getDate()}</b><span>${dt.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</span></div><div class="job-info"><div class="actions">${badge(j.status)}${contentBadge(jobContentMode(j))}${accountTag(j.accountId,j.accountName)}</div><h3>${esc(j.title)}</h3><p>${esc(j.error||'')}</p>${j.noteUrl?`<a class="source-link" href="${esc(j.noteUrl)}" target="_blank" rel="noopener noreferrer">查看笔记 ↗</a>`:''}<div class="actions">${btn('查看草稿','edit','ghost',`data-id="${j.draftId}"`)}${['scheduled','blocked'].includes(j.status)?btn('取消排期','job-cancel','ghost',`data-id="${j.id}"`):''}${j.status==='blocked'&&j.attempts===0?btn('重新入队','job-retry','light',`data-id="${j.id}"`):''}${j.status==='uncertain'?btn('核对结果','job-verify','light',`data-id="${j.id}"`):''}</div></div></article>`;}).join('')||`<div class="empty"><h3>暂无发布任务</h3>${btn('去创作台','nav','light','data-page="studio"')}</div>`}</div></section><aside><div class="panel"><h3>接入状态</h3>${connectors()}<p class="preview-caption">服务运行时执行排期。结果不明时停止自动重试。</p>${btn('账号管理','nav','ghost','data-page="accounts"')}</div></aside></div>`;}
function accounts(){const items=allAccounts().filter(a=>accountView==='archived'?a.archived:!a.archived);return topHead('账号管理',btn(icon('plus')+' 添加账号','account-new'))+`<div class="filters"><button class="filter ${accountView==='active'?'active':''}" data-action="account-view" data-view="active">账号列表</button><button class="filter ${accountView==='archived'?'active':''}" data-action="account-view" data-view="archived">已归档</button><span class="shared-note">产品资料和灵感库共用</span></div><div class="account-list">${items.map(a=>{const drafts=S.drafts.filter(d=>d.accountId===a.id),jobs=S.jobs.filter(j=>j.accountId===a.id);return `<article class="account-card"><div class="account-card-head"><div class="account-avatar">${a.type==='official'?'官':'小'}</div><div class="account-main"><div class="account-name"><h2>${esc(a.name)}</h2><span class="badge neutral">${a.type==='official'?'官方账号':'普通账号'}</span>${a.id===S.defaultAccountId?'<span class="badge">默认</span>':''}</div><p>${esc(a.handle||'未填写小红书号')}${a.profileUrl?` · <a href="${esc(a.profileUrl)}" target="_blank" rel="noopener noreferrer">主页 ↗</a>`:''}</p></div><span class="badge ${a.archived||!a.enabled?'neutral':''}">${a.archived?'已归档':a.enabled?'启用':'停用'}</span></div><div class="account-details"><div><span>发布目标</span><strong>${a.bridgeAccountId?esc(a.bridgeAccountId):'未配置'}</strong><small>${accountReady(a.id)?'配置就绪，待实际核对':'发布器未接通'}</small></div><div><span>草稿</span><strong>${drafts.filter(d=>d.status==='draft').length}</strong></div><div><span>待发布</span><strong>${jobs.filter(j=>['scheduled','blocked','uncertain','publishing'].includes(j.status)).length}</strong></div><div><span>已发布</span><strong>${jobs.filter(j=>j.status==='published').length}</strong></div></div>${a.notes?`<p class="account-notes">${esc(a.notes)}</p>`:''}<div class="account-actions">${btn(a.archived?'查看':'编辑','account-edit','light',`data-id="${a.id}"`)}${!a.archived?`${btn('每日任务','daily','light',`data-id="${a.id}"`)}${btn(a.enabled?'停用':'启用','account-toggle','ghost',`data-id="${a.id}"`)}${a.id!==S.defaultAccountId?btn('设为默认','account-default','ghost',`data-id="${a.id}"`):''}<span class="grow"></span>${btn('归档','account-archive','ghost',`data-id="${a.id}"`)}`:''}</div></article>`;}).join('')||'<div class="empty">暂无账号</div>'}</div>`;}

const assetKindLabels={model:'3D 模型',icon:'图标',image:'产品图片',brochure:'宣传册'};
const renderLabels={queued:'排队中',running:'渲染中',completed:'已完成',failed:'失败'};
function productAssets(){return S.productAssets||[];}
function productAsset(id){return productAssets().find(a=>a.id===id);}
function selectableAssets(){return productAssets().filter(a=>['image','icon'].includes(a.kind)).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));}
function isMainImageAsset(a){return a?.kind==='image'&&a.mime!=='image/svg+xml'&&!/\.svg$/i.test(a.originalName||a.name||'');}
function draftPhotos(d){return (d?.productAssetIds||[]).map(id=>productAsset(id)).filter(isMainImageAsset);}
function recentPhotoIds(){return selectableAssets().filter(isMainImageAsset).slice(0,2).map(a=>a.id);}
function draftThumbnail(d){const photo=draftPhotos(d)[0];return contentMode(d)==='text'?'<div class="draft-thumb draft-thumb-label">文字</div>':photo?`<img class="draft-thumb product-draft-thumb" src="${esc(assetFileUrl(photo))}" alt="${esc(photo.name)}">`:'<div class="draft-thumb draft-thumb-label">待配图</div>';}

function assetBytes(value){const n=Number(value)||0;return n>=1024*1024?`${(n/1024/1024).toFixed(1)} MB`:n>=1024?`${(n/1024).toFixed(1)} KB`:`${n} B`;}
function latestRender(id){return (S.productRenders||[]).filter(j=>j.assetId===id).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0];}
function assetFileUrl(a){return a.fileUrl||`/api/product-assets/${encodeURIComponent(a.id)}/file`;}
function assetPreviewUrl(a){const job=latestRender(a.id);return a.previewUrl||(job?.status==='completed'?job.previewUrl:'')||'';}
function assetTypeIcon(a){return icon(a.kind==='model'?'box':a.kind==='brochure'?'file':'image');}
function assetRenderControls(a){if(a.kind!=='model')return '';const job=latestRender(a.id),running=job&&['queued','running'].includes(job.status);return `<div class="asset-render"><select name="renderPreset" aria-label="${esc(a.name)}渲染视角"><option value="studio">标准视角</option><option value="front">正面</option><option value="angle">侧角</option></select>${btn(running?renderLabels[job.status]:'生成产品图','asset-render','light',`data-id="${a.id}"${!a.renderable||running?' disabled':''}`)}</div>${job?`<div class="asset-render-status ${job.status==='failed'?'is-error':''}"><span class="badge ${job.status==='failed'?'warn':['queued','running'].includes(job.status)?'neutral':''}">${renderLabels[job.status]||esc(job.status)}</span>${job.error?`<p>${esc(job.error)}</p>`:''}${job.status==='completed'&&job.imageAssetId?'<small>生成图已加入产品图片</small>':''}</div>`:a.renderStatus==='needs_setup'?'<p class="asset-render-hint">渲染环境待配置</p>':!a.renderable?'<p class="asset-render-hint">暂不支持此模型渲染</p>':''}`;}
function assetLibrary(){const items=productAssets().filter(a=>assetFilter==='all'||a.kind===assetFilter);return `<div class="filters asset-filters">${[['all','全部'],...Object.entries(assetKindLabels)].map(([key,label])=>`<button class="filter ${assetFilter===key?'active':''}" data-action="asset-filter" data-kind="${key}">${label}${key==='all'?'':` <span>${productAssets().filter(a=>a.kind===key).length}</span>`}</button>`).join('')}<span class="shared-note">${items.length} 项</span></div><div class="product-asset-grid">${items.map(a=>{const preview=assetPreviewUrl(a);return `<article class="asset-card"><button class="asset-preview" data-action="asset-preview" data-id="${a.id}" aria-label="预览 ${esc(a.name)}">${preview?`<img src="${esc(preview)}" alt="${esc(a.name)}预览" loading="lazy">`:`<span class="asset-placeholder">${assetTypeIcon(a)}<small>暂无预览</small></span>`}</button><div class="asset-card-body"><div class="asset-card-title"><h3>${esc(a.name||a.originalName)}</h3><span class="badge neutral">${assetKindLabels[a.kind]||esc(a.kind)}</span></div><p class="asset-file-meta">${esc(a.originalName||a.name)} · ${assetBytes(a.size)}</p>${a.description?`<p class="asset-description">${esc(a.description)}</p>`:''}${a.kind==='model'?`<p class="asset-storage-note">${a.storage==='linked'?'本地引用，不复制大文件':'本机模型文件'}</p>`:''}${assetRenderControls(a)}<div class="asset-card-actions">${btn('预览','asset-preview','ghost',`data-id="${a.id}"`)}<a class="btn ghost" href="${esc(assetFileUrl(a))}" download="${esc(a.originalName||a.name)}">下载原文件</a></div></div></article>`;}).join('')||'<div class="empty">暂无素材</div>'}</div>`;}
function product(){return topHead('产品资料',productTab==='assets'?btn(icon('plus')+' 上传素材','asset-upload'):'' )+`<div class="product-tabs"><button class="${productTab==='facts'?'active':''}" data-action="product-tab" data-tab="facts">产品资料</button><button class="${productTab==='assets'?'active':''}" data-action="product-tab" data-tab="assets">素材库 <span>${productAssets().length}</span></button></div>`+(productTab==='assets'?assetLibrary():productFacts());}
function assetPicker(selected=[],scope='draft'){const ids=Array.isArray(selected)?selected:[],available=selectableAssets(),items=[...ids.map(id=>available.find(a=>a.id===id)).filter(Boolean),...available.filter(a=>!ids.includes(a.id))],mainIds=ids.filter(id=>isMainImageAsset(productAsset(id)));return `<details class="asset-picker"${mainIds.length?'':' open'}><summary>产品素材 <span>${ids.length?`已选 ${ids.length} 项`:'请选择产品图片'}</span></summary>${items.length?`<div class="asset-pick-list">${items.map(a=>`<label class="asset-pick-row"><input type="checkbox" name="productAssetIds" value="${a.id}"${ids.includes(a.id)?' checked':''}>${assetPreviewUrl(a)?`<img src="${esc(assetPreviewUrl(a))}" alt="" loading="lazy">`:`<span class="asset-pick-placeholder">${assetTypeIcon(a)}</span>`}<span class="asset-pick-info"><strong>${esc(a.name||a.originalName)}</strong><small>${assetKindLabels[a.kind]} · ${assetBytes(a.size)} · ${isMainImageAsset(a)?'发布图片':'附加素材'}</small></span><span class="asset-order">${mainIds.includes(a.id)?'第 '+(mainIds.indexOf(a.id)+1)+' 张':''}</span></label>`).join('')}</div>`:'<p class="asset-picker-note">素材库暂无可用图片。</p>'}<p class="asset-picker-note">产品图片按勾选顺序发布，最多选择 9 个素材。图标随导出包附带，不作为主图。</p></details>`;}
function updateAssetPicker(picker,ids){picker.querySelector('summary span').textContent=ids.length?`已选 ${ids.length} 项`:'请选择产品图片';const photos=ids.filter(id=>isMainImageAsset(productAsset(id)));for(const input of picker.querySelectorAll('input[name=productAssetIds]')){const label=input.closest('.asset-pick-row').querySelector('.asset-order');label.textContent=photos.includes(input.value)?`第 ${photos.indexOf(input.value)+1} 张`:'';}}
function changeDraftMode(next){if(!edit||next===contentMode(edit))return true;if(next==='text'&&((edit.productAssetIds||[]).length||(edit.slides||[]).length)&&!confirm('切换为文字稿将清空当前图片和辅助分镜，是否继续？'))return false;edit.contentMode=next;if(next==='text'){edit.productAssetIds=[];edit.slides=[];}else{edit.productAssetIds=recentPhotoIds();edit.slides||=[];}dirty=true;slide=0;render();return true;}

function assetPreviewModal(id){const a=productAsset(id);if(!a)return;const preview=assetPreviewUrl(a),dimensions=a.metadata?.width&&a.metadata?.height?`${a.metadata.width} × ${a.metadata.height}`:'';modal('素材预览','',`<div class="asset-modal"><div class="asset-modal-preview">${preview?`<img src="${esc(preview)}" alt="${esc(a.name)}预览">`:`<span class="asset-placeholder">${assetTypeIcon(a)}<small>暂无预览</small></span>`}</div><div class="asset-modal-info"><h3>${esc(a.name||a.originalName)}</h3><p>${esc(a.originalName||a.name)}</p><p>${assetKindLabels[a.kind]||esc(a.kind)} · ${assetBytes(a.size)}${dimensions?' · '+esc(dimensions):''}</p>${a.sourceLabel?`<p>${esc(a.sourceLabel)}</p>`:''}${a.description?`<p>${esc(a.description)}</p>`:''}${a.kind==='model'&&a.storage==='linked'?'<p>本地引用，不复制大文件</p>':''}</div>${assetRenderControls(a)}<div class="modal-actions"><a class="btn light" href="${esc(assetFileUrl(a))}" download="${esc(a.originalName||a.name)}">下载原文件</a></div></div>`);}
function assetUploadModal(){modal('上传素材','',`<form id="asset-upload-form"><div class="field"><label for="asset-upload-kind">素材类型</label><select id="asset-upload-kind" name="kind"><option value="image">产品图片</option><option value="icon">图标</option><option value="brochure">宣传册</option></select></div><div class="field"><label for="asset-upload-file">文件</label><input id="asset-upload-file" type="file" name="assetFile" accept="image/png,image/jpeg,image/webp,image/svg+xml,application/pdf" required><small>单文件最多 20 MB</small></div><div class="modal-actions"><button class="btn" type="submit">上传</button></div></form>`);}
function productFacts(){const p=S.product;return `<div class="product-banner"><h2>${esc(p.name)}</h2><p>${esc(p.summary)}</p></div><div class="product-grid"><section class="editor"><form id="product-form"><div class="form-grid">${field('产品名称','name',p.name)}${field('品牌 / 团队','brand',p.brand)}</div>${field('当前产品阶段','stage',p.stage)}${field('产品一句话说明','summary',p.summary,'textarea')}${field('资料记录的产品能力 · 每行一条','facts',p.facts.join('\n'),'textarea','功能方向来自文档；结果性描述仍需当前实机验证。')}${field('必须讲清的使用条件 · 每行一条','conditions',p.conditions.join('\n'),'textarea')}${field('尚无依据的承诺 · 每行一条','restrictions',p.restrictions.join('\n'),'textarea')}${field('资料来源 · 每行一个 https 链接','sources',p.sources.join('\n'),'textarea')}<div class="actions"><button class="btn" type="submit">保存产品资料</button><small class="muted">会使未发布草稿的审核状态失效</small></div></form></section><aside><div class="panel"><h3>资料来源</h3><p class="preview-caption">已整理此前读取的资料快照。这里保存链接与产品事实，目前不会自动拉取飞书的新内容。</p>${p.sources.map((src,i)=>`<a class="source-link" href="${esc(src)}" target="_blank" rel="noopener noreferrer">${i===0?'产品说明与内测边界':'项目资料 '+(i+1)} ↗<small>${esc(new URL(src).hostname)}</small></a>`).join('')}<div class="note-box">资料更新后，请把最新能力和限制补进左侧；生成时会记录本次资料版本。</div><p class="preview-caption">最近保存：${date(p.updatedAt)}</p></div></aside></div>`;}
function workbenchImages(){return selectableAssets().filter(isMainImageAsset);}
function imageSourceOptions(value){return workbenchImages().map(a=>`<option value="${a.id}"${a.id===value?' selected':''}>${esc(a.name||a.originalName)}</option>`).join('');}
function imageJobsMarkup(){const jobs=(S.imageJobs||[]).slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));const statuses={queued:'排队中',generating:'生成中',completed:'已完成',failed:'失败'};return jobs.slice(0,12).map(job=>{const asset=productAsset(job.assetId);return `<article class="image-job"><div class="image-job-head"><span class="badge ${job.status==='failed'?'warn':['queued','generating'].includes(job.status)?'neutral':''}">${statuses[job.status]||esc(job.status)}</span><span>${job.mode==='edit'?'参考图改图':'生图'}</span><time>${date(job.createdAt)}</time></div>${asset?`<button class="image-job-result" data-action="asset-preview" data-id="${asset.id}"><img src="${esc(assetFileUrl(asset))}" alt="${esc(asset.name)}" loading="lazy"></button>`:''}<p class="image-job-prompt">${esc(job.prompt||'')}</p>${job.error?`<p class="image-job-error">${esc(job.error)}</p>`:''}${asset?`<div class="actions">${btn('手动调整','image-use','light',`data-id="${asset.id}"`)}<a class="btn ghost" href="${esc(assetFileUrl(asset))}" download="${esc(asset.originalName||asset.name)}">下载</a></div>`:''}</article>`;}).join('')||'<div class="empty">暂无图片任务</div>';}
function imageAIReferences(){const available=workbenchImages(),ids=imageReferenceIds.filter(id=>available.some(a=>a.id===id));imageReferenceIds=ids;return `<details class="asset-picker" open><summary>参考图片 <span>${ids.length} / 4</span></summary><div class="asset-pick-list">${available.map(a=>`<label class="asset-pick-row"><input type="checkbox" name="imageSourceIds" value="${a.id}"${ids.includes(a.id)?' checked':''}><img src="${esc(assetPreviewUrl(a)||assetFileUrl(a))}" alt="" loading="lazy"><span class="asset-pick-info"><strong>${esc(a.name||a.originalName)}</strong><small>${assetBytes(a.size)}</small></span></label>`).join('')||'<p class="asset-picker-note">请先上传产品图片。</p>'}</div></details>`;}
function imageAIPage(){const provider=S.imageProvider||{},ready=provider.ready===true;return `<div class="image-ai-grid"><section class="panel image-ai-controls"><form id="image-ai-form"><div class="image-provider"><span id="image-provider-status" class="badge ${ready?'':'neutral'}">${ready?'图片 API 已配置':'未配置图片 API'}</span><small id="image-provider-model">${ready?esc(provider.model||''):''}</small></div><div class="form-grid"><div class="field"><label for="image-ai-mode">方式</label><select id="image-ai-mode"><option value="generate"${imageAIMode==='generate'?' selected':''}>生成新图</option><option value="edit"${imageAIMode==='edit'?' selected':''}>参考图改图</option></select></div><div class="field"><label for="image-ai-size">尺寸</label><select id="image-ai-size">${[['1024x1024','方图 · 1024 × 1024'],['1024x1536','竖图 · 1024 × 1536'],['1536x1024','横图 · 1536 × 1024']].map(([v,t])=>`<option value="${v}"${imageSize===v?' selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label for="image-ai-prompt">要求</label><textarea id="image-ai-prompt" maxlength="2000" rows="7" placeholder="例如：保持产品外形，换成浅色桌面场景。">${esc(imagePrompt)}</textarea></div>${imageAIMode==='edit'?imageAIReferences():''}<div class="actions"><button id="image-ai-submit" class="btn" type="submit"${!ready?' disabled':''}>${imageAIMode==='edit'?'提交改图':'提交生图'}</button>${btn('复制要求','image-copy-prompt','light')}${btn('上传回图','asset-upload','ghost')}</div></form></section><section class="image-job-section"><div class="section-head"><h2>图片任务</h2></div><div id="image-job-list" class="image-job-list">${imageJobsMarkup()}</div></section></div>`;}
function imageAdjustPage(){const assets=workbenchImages();if(!assets.length)return `<div class="empty">暂无产品图片<br>${btn('上传图片','asset-upload','light')}</div>`;const asset=assets.find(a=>a.id===imageSourceId)||assets[0];imageSourceId=asset.id;const name=imageOutputName||`${(asset.name||asset.originalName).replace(/\.(png|jpe?g|webp)$/i,'')} - 调整.png`;return `<div class="image-adjust-grid"><section class="panel image-adjust-controls"><div class="field"><label for="image-adjust-source">来源图片</label><select id="image-adjust-source">${imageSourceOptions(asset.id)}</select></div><div class="form-grid"><div class="field"><label for="crop-ratio">比例</label><select id="crop-ratio">${['1:1','3:4','4:3'].map(v=>`<option${cropSettings.ratio===v?' selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="crop-fit">排布</label><select id="crop-fit"><option value="contain"${cropSettings.fit==='contain'?' selected':''}>保留全图</option><option value="cover"${cropSettings.fit==='cover'?' selected':''}>铺满裁切</option></select></div></div><div class="field crop-range"><label for="crop-zoom">缩放 <span id="crop-zoom-value">${Math.round(cropSettings.zoom*100)}%</span></label><input id="crop-zoom" type="range" min="1" max="3" step="0.01" value="${cropSettings.zoom}"></div><div class="field crop-range"><label for="crop-x">水平位置 <span id="crop-x-value">${cropSettings.x}</span></label><input id="crop-x" type="range" min="-100" max="100" step="1" value="${cropSettings.x}"></div><div class="field crop-range"><label for="crop-y">垂直位置 <span id="crop-y-value">${cropSettings.y}</span></label><input id="crop-y" type="range" min="-100" max="100" step="1" value="${cropSettings.y}"></div>${field('保存名称','image-output-name',name)}<p id="crop-error" class="image-job-error" hidden></p><div class="actions"><button id="crop-save" class="btn" data-action="image-save-crop" disabled>保存为新素材</button>${btn('重置','image-reset','light')}</div></section><section class="image-canvas-section"><div class="preview-top"><span>调整预览</span><span id="crop-dimensions"></span></div><div class="image-canvas-stage"><canvas id="image-crop-canvas" role="img" aria-label="调整后的产品图片预览"></canvas></div><p class="preview-source">${esc(asset.name||asset.originalName)}</p></section></div>`;}
function images(){return topHead('图片',btn(icon('plus')+' 上传图片','asset-upload','light'))+`<div class="product-tabs"><button data-action="image-tab" data-tab="adjust" class="${imageToolTab==='adjust'?'active':''}">手动调整</button><button data-action="image-tab" data-tab="ai" class="${imageToolTab==='ai'?'active':''}">AI 图片</button></div>`+(imageToolTab==='ai'?imageAIPage():imageAdjustPage());}
async function loadWorkbenchImage(asset){const key=asset.id+'@'+assetFileUrl(asset);if(imageAssetCache.has(key))return imageAssetCache.get(key);const promise=(async()=>{const blob=await originalAssetBlob(asset),url=URL.createObjectURL(blob),image=new Image();try{image.src=url;await image.decode();return image;}finally{URL.revokeObjectURL(url);}})();imageAssetCache.set(key,promise);promise.catch(()=>imageAssetCache.delete(key));return promise;}
async function drawWorkbenchCanvas(){const canvas=$('#image-crop-canvas'),button=$('#crop-save'),error=$('#crop-error'),asset=productAsset(imageSourceId);if(!canvas||!asset)return false;const token=++cropRevision;cropReady=false;if(button)button.disabled=true;if(error){error.hidden=true;error.textContent='';}try{const image=await loadWorkbenchImage(asset);if(token!==cropRevision||authRedirecting||!S||page!=='images'||imageToolTab!=='adjust')return false;const dimensions={'1:1':[1200,1200],'3:4':[1200,1600],'4:3':[1600,1200]},[width,height]=dimensions[cropSettings.ratio]||dimensions['3:4'];canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d'),naturalWidth=image.naturalWidth||image.width,naturalHeight=image.naturalHeight||image.height;if(!naturalWidth||!naturalHeight)throw Error('图片尺寸无法读取');const base=(cropSettings.fit==='cover'?Math.max:Math.min)(width/naturalWidth,height/naturalHeight),scale=base*cropSettings.zoom,drawWidth=naturalWidth*scale,drawHeight=naturalHeight*scale,x=(width-drawWidth)/2+cropSettings.x/100*Math.abs(width-drawWidth)/2,y=(height-drawHeight)/2+cropSettings.y/100*Math.abs(height-drawHeight)/2;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);ctx.drawImage(image,x,y,drawWidth,drawHeight);$('#crop-dimensions').textContent=`${width} × ${height}`;cropReady=true;if(button)button.disabled=false;return true;}catch(reason){if(token===cropRevision&&reason.code!=='AUTH_REQUIRED'&&error){error.textContent=reason.message||'图片无法读取';error.hidden=false;}return false;}}
function imageRequestPrompt(){const refs=(imageAIMode==='edit'?imageReferenceIds:[]).map(id=>productAsset(id)).filter(Boolean);return `${imageAIMode==='edit'?'参考图改图':'生成新图'}\n尺寸：${imageSize}\n参考素材：${refs.length?refs.map(a=>a.name||a.originalName).join('、'):'无'}\n\n产品外形保持不变：保持结构、比例、接口、按键和品牌标识，不增删硬件特征。\n\n${imagePrompt.trim()}`;}
async function updateImageJobView(){if(page!=='images'||authRedirecting||busy||$('#modal').open)return;try{await refresh(false);if(page!=='images'||authRedirecting||imageToolTab!=='ai')return;const list=$('#image-job-list'),ready=S.imageProvider?.ready===true;if(list)list.innerHTML=imageJobsMarkup();const status=$('#image-provider-status'),model=$('#image-provider-model'),submit=$('#image-ai-submit');if(status){status.textContent=ready?'图片 API 已配置':'未配置图片 API';status.className='badge'+(ready?'':' neutral');}if(model)model.textContent=ready?S.imageProvider.model||'':'';if(submit)submit.disabled=!ready||busy;}catch{}}
function settings(){return topHead('设置')+`<div class="settings-grid"><section class="panel"><h2>服务接入</h2>${authUser?.email?`<div class="session-user"><span>登录账号</span><strong>${esc(authUser.email)}</strong></div>`:''}${connectors()}<div class="note-box">本机单人工作台，运行数据保存在 runtime/。</div></section><section class="panel"><h2>AI 截图分析与创作</h2><ol class="setting-steps"><li>在项目目录复制 <code>.env.example</code> 为 <code>.env</code>。</li><li>填写 <code>REDPILOT_AI_KEY</code>、<code>REDPILOT_AI_MODEL</code>。</li><li>使用兼容服务时修改 <code>REDPILOT_AI_BASE_URL</code>。</li><li>重启本地服务。需支持图片输入与 JSON 模式。</li></ol><p class="preview-caption">启用后，点击分析或 AI 生成会向所配置服务发送对应截图、参考文字和产品资料。未配置时可用本地事实模板，页面会标明生成方式。</p></section><section class="panel"><h2>小红书发布器</h2><p class="preview-caption">当前没有内置小红书登录或发布驱动。可连接实现了本项目协议的发布桥，负责图集渲染、账号登录、实际发布与结果核对。</p><ol class="setting-steps"><li>填写 <code>REDPILOT_PUBLISH_URL</code>。</li><li>填写发布桥令牌 <code>REDPILOT_PUBLISH_TOKEN</code>。</li><li>在账号管理中填写各账号的发布目标 ID。</li><li>具体请求和幂等要求见仓库 <code>docs/publishing-bridge.md</code>。</li></ol><div class="note-box">仅填写配置不代表已连通。收到经核对的真实笔记链接后，任务才显示已发布。</div></section><section class="panel"><h2>数据备份</h2><p class="preview-caption">数据存储在本机，不会随代码上传。可下载资料、收藏索引、草稿和任务的 JSON 快照；图片文件需另外备份 runtime/uploads。</p>${btn(icon('download')+' 导出数据快照','backup','light')}<div class="spacer"></div><h3>运行记录</h3>${S.events.slice(0,5).map(e=>`<div class="event">${esc(e.message)}<time>${date(e.at)}</time></div>`).join('')||'<p class="preview-caption">还没有运行记录。</p>'}</section></div>`;}
function render(){if(!S)return;page=labels[page]?page:'overview';$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-symbol">↗</div><div><div class="brand-name">RedPilot<span class="brand-cn">薯航</span></div></div></div><nav class="nav" aria-label="工作台导航">${Object.entries(labels).map(([key,label],i)=>`<button class="${page===key?'active':''}" data-action="nav" data-page="${key}"${page===key?' aria-current="page"':''}>${icon(['grid','library','image','pen','calendar','users','box','settings'][i])}${label}${key==='library'?`<span class="count">${String(S.inspirations.length).padStart(2,'0')}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-card"><strong><span class="dot"></span>${esc(S.product.name)} 工作台</strong><p>产品宣传<br>${esc(S.product.brand)}</p></div><div class="local-label">${icon('box').replace('<svg ','<svg width="13" height="13" ')} 本机存储</div></div><div class="sidebar-auth">${btn('退出登录','logout','ghost')}</div></aside><main class="main"><div class="content">${({overview,library,images,studio,calendar,accounts,product,settings}[page])()}</div></main></div>`;if(page==='studio'&&edit)updatePreview();if(page==='images'&&imageToolTab==='adjust')drawWorkbenchCanvas();}
function modal(title,subtitle,body){$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="关闭弹窗">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
