function upload(target){uploadFiles=[];modal(target?'补充资料':'收藏灵感','同一篇笔记的多张截图会保存为一组。链接暂只保存来源，不自动抓取网页。',`<form id="upload-form" data-target="${target||''}">${field('收藏标题（选填）','ref-title','')}${field('笔记或账号链接（选填）','ref-url','','url')}<div class="field"><span>截图（选填）</span><label class="dropzone" id="dropzone">＋ 选择图片，或拖到这里<input id="upload-input" type="file" accept="image/png,image/jpeg,image/webp" multiple aria-label="选择参考截图"><small>每组最多 6 张 · 单张 8MB · 总计 16MB</small></label><div id="file-list" class="file-list"></div></div>${field('可见正文（选填）','ref-text','','textarea','链接无法读取时，可直接粘贴你看到的正文。')}${field('喜欢哪里 / 想学什么（选填）','ref-note','','textarea')}${field('标签 · 用逗号分隔（选填）','ref-tags','')}<div class="modal-actions"><button class="btn" type="submit">保存收藏</button></div></form>`);}
function formatAnalysis(value){if(Array.isArray(value))return `<ul>${value.map(x=>`<li>${typeof x==='object'?formatAnalysis(x):esc(x)}</li>`).join('')}</ul>`;if(value&&typeof value==='object')return Object.entries(value).map(([k,v])=>`<strong>${esc(analysisLabels[k]||k)}</strong>${formatAnalysis(v)}`).join('<br>');return `<p>${esc(value)}</p>`;}
const analysisLabels={topic:'选题角度',titlePattern:'标题结构',visual:'封面视觉',structure:'内容结构',adaptation:'产品适配',observations:'可见观察',inferences:'推断',unknown:'缺失信息',positioning:'账号定位',visible_cover_patterns:'可见封面规律',unknown_from_screenshot:'截图无法确定的内容',topic_angle:'选题角度',do_not_transfer:'不能沿用的结论'};
function reference(rid){const r=S.inspirations.find(x=>x.id===rid);if(!r)return;modal('收藏详情',r.scope||'只分析已提供的截图与文字，不推测未读取内容。',`<div class="detail-grid"><div class="detail-images">${r.assets.map((src,i)=>`<a href="${esc(src)}" target="_blank" rel="noopener"><img src="${esc(src)}" alt="参考截图 ${i+1}"></a>`).join('')||'<div class="empty">暂无截图</div>'}</div><div><form id="reference-form" data-id="${rid}">${field('收藏标题','detail-title',r.title)}${field('标签 · 用逗号分隔','detail-tags',r.tags.join('，'))}<label class="check-label"><input type="checkbox" name="pool"${r.pool?' checked':''}>加入每日选题池</label><div class="actions" style="margin-top:15px"><button class="btn light" type="submit">保存修改</button>${btn('补充截图 / 正文','upload','ghost',`data-id="${rid}"`)}</div></form>${r.url?`<a class="source-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">查看原始链接 ↗</a>`:''}<p class="preview-caption">${r.method==='editorial_seed'?'以下为此前人工浏览整理的分析样例。':r.method==='ai'?'以下由已配置模型分析，仅基于提供的资料。':'尚未执行 AI 分析。'}<br>${r.note?'备注：'+esc(r.note):''}</p>${r.text?`<details class="analysis-block"><summary>已保存的参考正文</summary><p>${esc(r.text)}</p></details>`:''}${r.analysis?Object.entries(r.analysis).map(([k,v])=>`<section class="analysis-block"><h3>${esc(analysisLabels[k]||k)}</h3>${formatAnalysis(v)}</section>`).join(''):'<div class="note-box">补充截图或正文后可调用 AI 分析。只有链接时，不会假装已经读过内容。</div>'}</div></div><div class="modal-actions">${btn('删除收藏','delete-ref','danger',`data-id="${rid}"`)}<span class="grow"></span>${btn(icon('spark')+' 分析参考','analyze','light',`data-id="${rid}"`)}${btn('参考创作','generate','',`data-id="${rid}"`)}</div>`);}
function accountModal(id){const a=accountById(id),readonly=Boolean(a?.archived);modal(readonly?'账号详情':a?'编辑账号':'添加账号','',`<form id="account-form" data-id="${a?.id||''}"><fieldset${readonly?' disabled':''}><div class="form-grid">${field('账号名称','account-name',a?.name||'')}<div class="field"><label for="account-type">类型</label><select id="account-type" name="type"><option value="official"${a?.type==='official'?' selected':''}>官方账号</option><option value="personal"${!a||a.type==='personal'?' selected':''}>普通账号</option></select></div></div><div class="form-grid">${field('小红书号（选填）','account-handle',a?.handle||'')}${field('主页链接（选填）','account-profile',a?.profileUrl||'','url')}</div>${field('发布目标 ID（选填）','account-bridge',a?.bridgeAccountId||'','text','与发布器中的账号 ID 对应，填写后仍需在发布器完成登录。')}${field('备注（选填）','account-notes',a?.notes||'','textarea')}<label class="check-label"><input name="enabled" type="checkbox"${!a||a.enabled?' checked':''}>启用账号</label></fieldset>${readonly?'<div class="note-box">已归档，保留历史记录。</div>':'<div class="modal-actions"><button class="btn" type="submit">保存账号</button></div>'}</form>`);}
function generateModal(rid){if(dirty){toast('请先保存当前草稿');return;}if(!activeAccounts().length){toast('请先添加账号');return;}generationAssetIds=recentPhotoIds();modal('新建草稿','',`<form id="generate-form">${accountSelect('gen-account',chosenAccount()?.archived?S.defaultAccountId:chosenAccount()?.id||S.defaultAccountId)}${modeSelect('gen','image')}<div id="gen-image-options">${assetPicker(generationAssetIds,'generate')}</div><p id="gen-native-note" class="mode-note" hidden>${nativeTextHint()}</p><div class="field"><label for="gen-ref">参考灵感</label><select name="referenceId" id="gen-ref"><option value="">不选参考 · 从产品资料开始</option>${S.inspirations.map(r=>`<option value="${r.id}"${r.id===rid?' selected':''}>${esc(r.title)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="gen-mode">借鉴方式</label><select name="mode" id="gen-mode"><option>综合借鉴</option><option>学习封面排版</option><option>学习文案结构</option></select></div><div class="field"><label for="gen-method">创作方式</label><select name="method" id="gen-method"><option value="${S.capabilities.ai?'ai':'template'}">${S.capabilities.ai?'AI 分析与创作':'本地事实模板（未启用 AI）'}</option>${S.capabilities.ai?'<option value="template">本地事实模板</option>':''}</select></div></div>${field('这篇想讲什么（选填）','instruction','','textarea','例如：学习这个问题式封面，讲备用机里真正需要留下的功能。')}<div class="note-box">${S.capabilities.ai?'AI 会收到所选截图、参考分析和产品资料。生成结果需要核对事实和素材。':'本地模板按已保存的产品事实排版，不执行截图识别、自由改写或参考风格迁移。你的创作要求会保留在草稿中。'}</div><div class="modal-actions"><button class="btn" type="submit">${icon('spark')} 创建草稿</button></div></form>`);}
function daily(accountId){const a=accountById(accountId)||chosenAccount();if(!a)return toast('请先添加账号');if(a.archived)return toast('账号已归档');const settings=a.settings,share=imageShareValue(settings);modal('每日任务','',`<form id="settings-form" data-id="${a.id}">${accountSelect('daily-account',a.id)}<label class="check-label"><input name="enabled" type="checkbox"${settings.enabled?' checked':''}>启用每日任务</label><div class="spacer"></div><div class="form-grid">${field('执行时间','time',settings.time,'time')}${field('时区','timezone',settings.timezone,'text','例如 Asia/Shanghai')}</div><div class="field"><label for="daily-mode">发布模式</label><select name="mode" id="daily-mode"><option value="automatic"${settings.mode==='automatic'?' selected':''}>自动生成并发布</option><option value="review"${settings.mode==='review'?' selected':''}>审核后发布</option></select></div><div class="field"><label for="daily-image-share">图文占比</label><div class="content-ratio"><input id="daily-image-share" name="imageShare" type="number" min="0" max="100" step="1" required value="${share}"><span>%</span><small id="daily-text-share">文字 ${100-share}%</small></div></div><div class="note-box">${!a.enabled?'账号已停用，每日任务暂停执行。<br>':''}仅在本地服务运行时执行，每天一次。AI 或发布器未配置时记录原因。</div><div class="modal-actions"><button class="btn" type="submit">保存设置</button></div></form>`);}

function schedule(did){const d=S.drafts.find(x=>x.id===did);if(dirty){toast('请先保存草稿并核对通过');return;}const a=accountById(d.accountId);const next=new Date(Date.now()+3600000);const local=new Date(next-next.getTimezoneOffset()*60000).toISOString().slice(0,16);modal('安排发布','',`<form id="schedule-form" data-id="${did}" data-account="${esc(d.accountId)}"><div class="schedule-target"><span>目标账号</span><strong>${esc(a?.name||'未分配账号')}</strong><small>${esc(d.title)}</small></div>${field('发布时间 · 按浏览器时区','scheduledAt',local,'datetime-local')}<div class="note-box">${!a?.enabled||a?.archived?'账号已停用或归档，请先调整草稿归属。':!d.approved?'请先在创作台核对图文。':!accountReady(d.accountId)?'该账号发布器未接通。可先保存排期，到时会标记待处理。':'发布前会重新检查资料版本。'}</div><div class="modal-actions"><button class="btn" type="submit"${!a?.enabled||a?.archived?' disabled':''}>确认排期</button></div></form>`);}

function textPreview(d){return `<article class="native-text-preview"><h3>${esc(d.title)}</h3><p class="native-text-body">${esc(d.body)}</p><p class="native-text-tags">${d.tags.map(t=>'#'+esc(t)).join(' ')}</p><div class="native-text-note">${nativeTextHint()}</div></article>`;}
function updatePreview(){if(!edit||!$('#draft-preview'))return;const photos=draftPhotos(edit),text=contentMode(edit)==='text';slide=Math.max(0,Math.min(slide,Math.max(0,photos.length-1)));$('#draft-preview').innerHTML=text?textPreview(edit):photos.length?`<img class="product-photo-preview" src="${esc(assetFileUrl(photos[slide]))}" alt="${esc(photos[slide].name)}">`:`<div class="missing-photo-preview">请选择至少一张产品图片。<small>图标和 SVG 不能作为图文主图。</small></div>`;$('#page-indicator').textContent=text?'文字稿':photos.length?`${slide+1} / ${photos.length}`:'未选择图片';$('.preview-pagination').innerHTML=text?'':photos.map((_,i)=>`<button data-action="slide" data-index="${i}" class="${i===slide?'active':''}" aria-label="预览第${i+1}张图片">${i+1}</button>`).join('');$('#preview-source').textContent=!text&&photos.length?`第 ${slide+1} 张 · ${photos[slide].name}`:'';$('#title-count').textContent=`${[...edit.title].length} / 20`;$('#body-count').textContent=`${[...edit.body].length} / 1000`;$('#save-state').textContent=dirty?'有修改，待保存':`已保存 · v${edit.revision}`;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function originalAssetBlob(asset){const response=await fetch(assetFileUrl(asset),{credentials:'same-origin'});if(response.status===401)throw authRequired();if(!response.ok)throw Error(`素材「${asset.name}」读取失败`);return response.blob();}
function crc32(buf){let crc=-1;for(const n of buf){crc^=n;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^-1)>>>0;}
function zip(files){const parts=[],central=[],encoder=new TextEncoder();let offset=0;for(const [name,data] of files){const nameBytes=encoder.encode(name),checksum=crc32(data),header=new Uint8Array(30+nameBytes.length),v=new DataView(header.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,checksum,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,nameBytes.length,true);header.set(nameBytes,30);parts.push(header,data);const c=new Uint8Array(46+nameBytes.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,checksum,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,nameBytes.length,true);cv.setUint32(42,offset,true);c.set(nameBytes,46);central.push(c);offset+=header.length+data.length;}const centralSize=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
function safeAssetFilename(name){return String(name||'asset').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').replace(/^\.+/,'').slice(0,180)||'asset';}
async function exportPack(){const d=edit;if(!d)return;const text=contentMode(d)==='text',encoder=new TextEncoder(),files=[['post.txt',encoder.encode(`${d.title}\n\n${d.body}\n\n${d.tags.map(t=>'#'+t).join(' ')}`)]];if(text){files.push(['README.txt',encoder.encode('文字稿。发布端使用原生默认配图，具体样式在发布端选择。\n此包仅包含文案与说明。\n')]);}else{const ids=[...new Set(d.productAssetIds||[])],assets=ids.map(id=>productAsset(id)),photos=draftPhotos(d);if(assets.some(a=>!a||!['image','icon'].includes(a.kind)))throw Error('部分素材已不可用，请重新选择');if(!photos.length)throw Error('请先选择至少一张产品图片，图标或 SVG 不算主图');toast('正在打包产品图片…');for(let i=0;i<photos.length;i++){const asset=photos[i];files.push([`${String(i+1).padStart(2,'0')}-${safeAssetFilename(asset.originalName||asset.name)}`,new Uint8Array(await (await originalAssetBlob(asset)).arrayBuffer())]);}const extras=assets.filter(a=>!isMainImageAsset(a));if(extras.length){files.push(['sources/README.txt',encoder.encode('附加素材，不作为本篇发布主图。\n')]);for(let i=0;i<extras.length;i++){const asset=extras[i];files.push([`sources/${String(i+1).padStart(2,'0')}-${safeAssetFilename(asset.originalName||asset.name)}`,new Uint8Array(await (await originalAssetBlob(asset)).arrayBuffer())]);}}if(d.slides?.length)files.push(['storyboard.txt',encoder.encode('辅助分镜，仅供策划，不作为发布图片。\n\n'+d.slides.map((p,i)=>`${i+1}. ${p.headline}\n${p.body}`).join('\n\n'))]);files.push(['README.txt',encoder.encode('图文稿。按文件序号使用所选产品原图，未叠加标题或自动生成文字卡。\n')]);}download(zip(files),'RedPilot-'+d.title.replace(/[/\\:*?"<>|]/g,'')+'.zip');toast(text?'文案已导出':'产品图片与文案已导出');}
function split(value){return String(value||'').split(/[，,\n]/).map(x=>x.trim()).filter(Boolean);}
function splitLines(value){return String(value||'').split('\n').map(x=>x.trim()).filter(Boolean);}
function addFiles(files){const next=[...uploadFiles,...files];if(next.length>6)return toast('每组最多 6 张截图');if(next.some(f=>f.size>8*1024*1024)||next.reduce((n,f)=>n+f.size,0)>16*1024*1024)return toast('单张最多 8MB，总计最多 16MB');if(next.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type)))return toast('仅支持 PNG、JPEG、WebP');uploadFiles=next;$('#file-list').textContent=next.map(f=>f.name).join(' · ');}
const fileData=f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,data:reader.result.split(',')[1]});reader.onerror=()=>reject(Error('无法读取图片'));reader.readAsDataURL(f);});
async function action(el){const a=el.dataset.action,key=el.dataset.id;if(a==='logout'&&dirty&&!confirm('有未保存的修改，确定退出登录？'))return;if(a==='close'){if(!busy)$('#modal').close();return;}if(a==='nav')return nav(el.dataset.page);if(a==='upload')return upload(key);if(a==='reference')return reference(key);if(a==='generate')return generateModal(key);if(a==='daily')return daily(key);if(a==='product-tab'){productTab=el.dataset.tab;render();return;}if(a==='image-tab'){imageToolTab=el.dataset.tab;render();return;}if(a==='image-use'){imageSourceId=key;imageOutputName='';imageToolTab='adjust';cropSettings={...cropSettings,zoom:1,x:0,y:0};nav('images');return;}if(a==='image-reset'){cropSettings={...cropSettings,zoom:1,x:0,y:0};render();return;}if(a==='asset-filter'){assetFilter=el.dataset.kind;render();return;}if(a==='asset-preview')return assetPreviewModal(key);if(a==='asset-upload')return assetUploadModal();if(a==='account-new')return accountModal();if(a==='account-edit')return accountModal(key);if(a==='account-view'){accountView=el.dataset.view;render();return;}if(a==='schedule')return schedule(key);if(a==='edit'){selected=key;const d=S.drafts.find(x=>x.id===key);if(d&&accountFilter!=='all'&&d.accountId!==accountFilter)accountFilter=d.accountId;return nav('studio');}if(a==='filter'){filter=el.dataset.filter;render();return;}if(a==='slide'){slide=Number(el.dataset.index);updatePreview();$('.preview-pagination').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===slide));return;}
if(a==='add-slide'||a==='remove-slide'){if(a==='add-slide'){if(edit.slides.length>=9)return toast('最多 9 页');edit.slides.push({headline:'新的一页',body:''});}else{edit.slides.splice(Number(el.dataset.index),1);}dirty=true;slide=Math.min(slide,edit.slides.length-1);render();updatePreview();return;}
if(a==='history'){const d=S.drafts.find(x=>x.id===key);return modal('历史版本','保留最近 20 次保存前的内容版本。',d.history.map(h=>`<details class="history-item"><summary>${date(h.at)} · ${esc(h.title)}</summary><p>${esc(h.body)}</p>${btn('复制该版文案','copy-history','light',`data-index="${d.history.indexOf(h)}"`)}</details>`).join('')||'<div class="empty">还没有历史版本。保存修改后会在这里出现。</div>');}
if(a==='copy-history'){const h=draftCurrent().history[Number(el.dataset.index)];await navigator.clipboard.writeText(h.title+'\n\n'+h.body);toast('已复制历史文案');return;}
if(a==='backup'){const {capabilities,draftChecks,...data}=S;download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'redpilot-backup.json');return;}
if(busy)return;busy=true;el.disabled=true;try{if(a==='analyze'){toast('正在分析提供的截图与文字…');await api(`inspirations/${key}/analyze`,{});await refresh(false);reference(key);toast('分析已保存');}
else if(a==='logout'){await api('auth/logout',{});authRequired();}
else if(a==='image-copy-prompt'){await navigator.clipboard.writeText(imageRequestPrompt());toast('要求已复制');}
else if(a==='image-save-crop'){if(!await drawWorkbenchCanvas()||!cropReady)throw Error('请先选择并加载图片');const canvas=$('#image-crop-canvas'),blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error('图片保存失败')),'image/png'));let name=safeAssetFilename($('#image-output-name').value||'产品图片.png');if(!/\.png$/i.test(name))name+='.png';const result=await api('product-assets/upload',{...(await fileData(new File([blob],name,{type:'image/png'}))),kind:'image'});await refresh(false);imageSourceId=result.id||result.item?.id||imageSourceId;imageOutputName='';cropSettings={...cropSettings,zoom:1,x:0,y:0};render();toast('已保存到素材库');}
else if(a==='asset-render'){const preset=el.closest('.asset-card,.asset-modal').querySelector('select[name=renderPreset]').value;await api(`product-assets/${key}/render`,{preset});if($('#modal').open)$('#modal').close();productTab='assets';await refresh();toast('已加入渲染队列');}
else if(a==='approve'){if(dirty)throw Error('请先保存草稿，再标记核对通过');await api(`drafts/${key}/approve`,{});edit=null;await refresh();toast('已标记核对通过');}
else if(a==='duplicate'){const d=await api(`drafts/${key}/duplicate`,{accountId:accountById(draftCurrent()?.accountId)?.archived?S.defaultAccountId:draftCurrent()?.accountId});selected=d.id;edit=null;dirty=false;if(accountFilter!=='all')accountFilter=d.accountId;await refresh();toast('已复制为新草稿');}
else if(a==='account-toggle'){const account=accountById(key);await api(`accounts/${key}`,{enabled:!account.enabled},'PUT');await refresh();toast(account.enabled?'账号已停用':'账号已启用');}
else if(a==='account-default'){await api(`accounts/${key}/default`,{});await refresh();toast('已设为默认账号');}
else if(a==='account-archive'){if(!confirm('归档这个账号？历史草稿和发布记录会保留。'))return;await api(`accounts/${key}/archive`,{});if(accountFilter===key)accountFilter='all';await refresh();toast('账号已归档');}
else if(a==='delete-ref'){if(!confirm('删除这份收藏？已生成的草稿会保留。'))return;await api(`inspirations/${key}`,{},'DELETE');$('#modal').close();await refresh();toast('收藏已删除');}
else if(a.startsWith('job-')){await api(`jobs/${key}/${a.slice(4)}`,{});await refresh();toast('任务状态已更新');}
else if(a==='download-slide'){const asset=draftPhotos(edit)[slide];if(!asset)throw Error('请先选择产品图片');download(await originalAssetBlob(asset),safeAssetFilename(asset.originalName||asset.name));}
else if(a==='export')await exportPack();}catch(e){toast(e.message);}finally{busy=false;el.disabled=false;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el);}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='image-ai-prompt'){imagePrompt=t.value;return;}if(t.id==='image-output-name'){imageOutputName=t.value;return;}if(['crop-zoom','crop-x','crop-y'].includes(t.id)){const key=t.id.slice(5);cropSettings[key]=Number(t.value);$('#'+t.id+'-value').textContent=key==='zoom'?Math.round(cropSettings.zoom*100)+'%':t.value;drawWorkbenchCanvas();return;}if(t.name==='imageSourceIds'){if(t.checked&&!imageReferenceIds.includes(t.value)&&imageReferenceIds.length>=4){t.checked=false;toast('最多选择 4 张参考图');return;}imageReferenceIds=t.checked?[...new Set([...imageReferenceIds,t.value])]:imageReferenceIds.filter(id=>id!==t.value);t.closest('.asset-picker').querySelector('summary span').textContent=imageReferenceIds.length+' / 4';return;}if(t.id==='daily-image-share'){const v=Number(t.value);$('#daily-text-share').textContent=t.value!==''&&Number.isInteger(v)&&v>=0&&v<=100?`文字 ${100-v}%`:'文字 —';return;}if(t.name==='productAssetIds'){const form=t.closest('form'),picker=t.closest('.asset-picker'),ids=form.id==='generate-form'?generationAssetIds:edit.productAssetIds||[];if(t.checked&&!ids.includes(t.value)&&ids.length>=9){t.checked=false;toast('最多选择 9 个素材');return;}const next=t.checked?[...new Set([...ids,t.value])]:ids.filter(id=>id!==t.value);updateAssetPicker(picker,next);if(form.id==='generate-form')generationAssetIds=next;else{edit.productAssetIds=next;dirty=true;updatePreview();}return;}if(t.id==='library-search'){query=t.value;const start=t.selectionStart;render();$('#library-search').focus();try{$('#library-search').setSelectionRange(start,start);}catch{}return;}if(t.closest('#draft-form')){if(t.name==='contentMode')return;if(t.dataset.slide!==undefined)edit.slides[Number(t.dataset.slide)][t.dataset.key]=t.value;else if(t.name==='tags')edit.tags=split(t.value);else if(t.name==='gaps')edit.gaps=splitLines(t.value);else if(t.name==='accountId')edit.accountId=t.value;else if(['title','body','series'].includes(t.name))edit[t.name]=t.value;dirty=true;updatePreview();}});
document.addEventListener('change',e=>{if(e.target.id==='image-adjust-source'){imageSourceId=e.target.value;imageOutputName='';cropSettings={...cropSettings,zoom:1,x:0,y:0};render();return;}if(e.target.id==='crop-ratio'||e.target.id==='crop-fit'){cropSettings[e.target.id==='crop-ratio'?'ratio':'fit']=e.target.value;drawWorkbenchCanvas();return;}if(e.target.id==='image-ai-size'){imageSize=e.target.value;return;}if(e.target.id==='image-ai-mode'){imageAIMode=e.target.value;if(imageAIMode==='edit'&&!imageReferenceIds.length){const id=imageSourceId||workbenchImages()[0]?.id;if(id)imageReferenceIds=[id];}render();return;}if(e.target.id==='gen-content-mode'){const text=e.target.value==='text';$('#gen-image-options').hidden=text;$('#gen-native-note').hidden=!text;$('#gen-image-options').querySelectorAll('input').forEach(input=>input.disabled=text);return;}if(e.target.id==='draft-content-mode'){if(!changeDraftMode(e.target.value))e.target.value=contentMode(edit);return;}if(e.target.id==='account-filter'){if(dirty&&!confirm('放弃未保存的修改？')){e.target.value=accountFilter;return;}accountFilter=e.target.value;selected=null;edit=null;dirty=false;slide=0;render();return;}if(e.target.id==='daily-account'){daily(e.target.value);return;}if(e.target.id==='upload-input')addFiles(e.target.files);if(e.target.id==='draft-select'){if(dirty&&!confirm('放弃未保存的修改？')){e.target.value=selected;return;}selected=e.target.value;edit=null;dirty=false;slide=0;render();}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.add('dragging');}});
document.addEventListener('dragleave',e=>{if(e.target.closest('#dropzone'))$('#dropzone').classList.remove('dragging');});
document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.remove('dragging');addFiles(e.dataTransfer.files);}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=e.target,fd=new FormData(f),values=Object.fromEntries(fd),submit=f.querySelector('button[type=submit]');busy=true;if(submit)submit.disabled=true;try{if(f.id==='upload-form'){const result=await api('inspirations',{title:values['ref-title']||uploadFiles[0]?.name||'链接灵感',url:values['ref-url'],text:values['ref-text'],note:values['ref-note'],tags:split(values['ref-tags']),targetId:f.dataset.target||undefined,files:await Promise.all(uploadFiles.map(fileData))});$('#modal').close();await refresh();toast(result.merged?'已合并到现有收藏':'灵感已保存');}
else if(f.id==='image-ai-form'){if(!S.imageProvider?.ready)throw Error('未配置图片 API');if(!imagePrompt.trim())throw Error('请填写生成要求');if(imageAIMode==='edit'&&!imageReferenceIds.length)throw Error('请先选择参考图片');await api('image-jobs',{mode:imageAIMode,prompt:imageRequestPrompt(),sourceAssetIds:imageAIMode==='edit'?imageReferenceIds:[],size:imageSize});await refresh(false);render();toast('已提交图片任务');}
else if(f.id==='asset-upload-form'){const file=f.querySelector('input[type=file]').files[0];if(!file)throw Error('请选择文件');if(file.size>20*1024*1024)throw Error('单文件最多 20 MB');const uploaded=await api('product-assets/upload',{...(await fileData(file)),kind:values.kind});$('#modal').close();productTab='assets';if(page==='images'&&values.kind==='image'){imageSourceId=uploaded.id||uploaded.item?.id||imageSourceId;imageOutputName='';imageToolTab='adjust';cropSettings={...cropSettings,zoom:1,x:0,y:0};}await refresh();toast('素材已上传');}
else if(f.id==='reference-form'){await api('inspirations/'+f.dataset.id,{title:values['detail-title'],tags:split(values['detail-tags']),pool:fd.has('pool')},'PUT');await refresh(false);reference(f.dataset.id);toast('收藏已更新');}
else if(f.id==='generate-form'){toast('正在创建草稿…');const d=await api('drafts',{...values,productAssetIds:values.contentMode==='text'?[]:generationAssetIds});if(accountFilter!=='all')accountFilter=d.accountId;selected=d.id;edit=null;dirty=false;$('#modal').close();await refresh(false);nav('studio');toast(d.method==='ai'?'AI 草稿已保存，请核对图文':'本地事实模板已创建');}
else if(f.id==='draft-form'){await api('drafts/'+edit.id,{...edit,contentMode:contentMode(edit),...(contentMode(edit)==='text'?{slides:[],productAssetIds:[]}:{})},'PUT');if(accountFilter!=='all')accountFilter=edit.accountId;dirty=false;edit=null;await refresh();toast('草稿已保存');}
else if(f.id==='account-form'){const data={name:values['account-name'],type:values.type,handle:values['account-handle'],profileUrl:values['account-profile'],bridgeAccountId:values['account-bridge'],notes:values['account-notes'],enabled:fd.has('enabled')};await api(f.dataset.id?'accounts/'+f.dataset.id:'accounts',data,f.dataset.id?'PUT':'POST');$('#modal').close();await refresh();toast('账号已保存');}
else if(f.id==='product-form'){await api('product',{...values,facts:splitLines(values.facts),conditions:splitLines(values.conditions),restrictions:splitLines(values.restrictions),sources:splitLines(values.sources)},'PUT');await refresh();toast('产品资料已更新，旧稿需要重新核对');}
else if(f.id==='settings-form'){await api(`accounts/${f.dataset.id}/settings`,{...values,enabled:fd.has('enabled'),imageShare:Number(values.imageShare)},'PUT');$('#modal').close();await refresh();toast('每日设置已保存');}
else if(f.id==='schedule-form'){await api('drafts/'+f.dataset.id+'/schedule',{scheduledAt:new Date(values.scheduledAt).toISOString(),accountId:f.dataset.account});$('#modal').close();await refresh(false);nav('calendar');toast('排期已保存');}}catch(err){toast(err.message);}finally{busy=false;if(submit)submit.disabled=false;}});
window.addEventListener('pageshow',restoreSession);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next!==page)nav(next);});
$('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
async function bootstrap(){const session=await api('auth/session',undefined,'GET');if(!session.authenticated)throw authRequired();authUser=session.user||null;await refresh();}
bootstrap().catch(e=>{if(e.code==='AUTH_REQUIRED')return;$('#app').innerHTML='<div class="loading">工作台暂时无法打开。请检查本地服务，再刷新页面。</div>';toast(e.message);});
setInterval(()=>{if(!dirty&&!busy&&!$('#modal').open&&page!=='studio'&&page!=='images'&&(page!=='product'||productTab==='assets'))refresh().catch(()=>{});},30000);

setInterval(()=>{if(!authRedirecting)validateSession();},60000);

setInterval(updateImageJobView,5000);
